function DeleteProject() {
  const [open, setOpen] = useState(false);
  return (
    <>
      <Button variant="soft" tone="danger" onClick={() => setOpen(true)}>Delete project</Button>
      <AlertDialog
        open={open}
        onOpenChange={setOpen}
        title="Delete project?"
        description="This action cannot be undone."
        intent="danger"
        confirmLabel="Delete"
        onConfirm={() => setOpen(false)}
      />
    </>
  );
}

function Shell() {
  const [view, setView] = React.useState("overview");
  return (
    <div className="h-[420px] overflow-hidden rounded-[var(--radius-panel)] border border-hairline">
      <AppFrame
        className="h-full"
        sidebar={
          <Sidebar width="w-56">
            <SidebarHeader><Text as="span" weight="semibold">Acme</Text></SidebarHeader>
            <SidebarBody>
              <SidebarSection title="Workspace">
                <SidebarNavItem label="Overview" active={view === "overview"} onClick={() => setView("overview")} />
                <SidebarNavItem label="Reports" active={view === "reports"} onClick={() => setView("reports")} />
              </SidebarSection>
            </SidebarBody>
          </Sidebar>
        }
      >
        <TopBar className="gap-2"><SidebarTrigger /><Text as="span" weight="medium">{view}</Text></TopBar>
        <div className="min-h-0 flex-1 overflow-y-auto p-4">
          <Grid columns="auto" minWidth="sm" gap="3"><Card padding="md">One</Card><Card padding="md">Two</Card><Card padding="md">Three</Card></Grid>
        </div>
      </AppFrame>
    </div>
  );
}

function EditableSnippet() {
  const [code, setCode] = useState('export function Hello() {\n  return <Button>Hello</Button>;\n}\n');
  return <CodeEditor value={code} onChange={setCode} filename="Hello.tsx" label="Hello component source" />;
}

function RenameProject() {
  const [open, setOpen] = useState(false);
  return (
    <>
      <Button variant="soft" onClick={() => setOpen(true)}>Rename project</Button>
      <Dialog
        open={open}
        onOpenChange={setOpen}
        size="md"
        title="Rename project"
        footer={
          <>
            <Button variant="ghost" onClick={() => setOpen(false)}>Cancel</Button>
            <Button onClick={() => setOpen(false)}>Save</Button>
          </>
        }
      >
        <TextField label="Project name" defaultValue="Website redesign" />
      </Dialog>
    </>
  );
}
